    public static function commands():array {return self::COMMANDS;}
    public static function definitions():array {
        $out=[];
        foreach(self::COMMANDS as $name=>$command) {
            $definition=['name'=>$name,'module'=>'forms','operation'=>$command['operation'],'app'=>'forms',
                'description'=>$command['description'].($command['read']?'':' First preview without changing data. Show the complete effects and get approval, then repeat with confirm:true, plan_state and operation_id. A stale preview writes nothing.'),
                'inputSchema'=>$command['inputSchema']];
            if(!$command['read']) {
                $definition['inputSchema']['properties']+=['plan_state'=>\OCA\Mcp\Mcp\Confirmation\PlanState::property(),
                    'operation_id'=>\OCA\Mcp\Mcp\Operations\OperationJournal::property(),
                    'confirm_shared'=>['type'=>'boolean','description'=>'Only after reviewing effects on a resource owned by another person.']];
            }
            if(isset($command['grantAnyOf']))$definition['grantAnyOf']=$command['grantAnyOf'];
            if($name==='forms_update')$definition['grantAnyOf']=['edit','public_link','configure_notifications'];
            if(in_array($name,['forms_read_response','forms_download_results','forms_export_results','forms_link_results_file'],true)) {
                $definition['grantAnyOf']=[$command['operation'],'read_respondents','read_response_files'];
            }
            if(in_array($name,['forms_read_admin_settings','forms_update_admin_settings'],true))$definition['requiresAdmin']=true;
            if(isset($command['grantAllOf']))$definition['grantAllOf']=$command['grantAllOf'];
            $out[$name]=$definition;
        }
        return $out;
    }
    public static function readOnly(string $name):bool {return self::COMMANDS[$name]['read']??throw new \InvalidArgumentException('Unknown Forms tool');}
    public static function grants():array {
        return array_values(array_unique([...array_column(self::COMMANDS,'operation'),'public_link','read_respondents','configure_notifications']));
    }
}
